package com.ntd.csdl;
import com.ntd.csdl.service.*;import com.ntd.csdl.entity.*;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.mock.web.MockMultipartFile;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;
import java.util.*;import java.nio.file.*;import java.io.*;import javax.imageio.ImageIO;import java.awt.image.BufferedImage;import java.math.BigDecimal;
class RoomListingTests {
 JdbcTemplate jdbc;RoomListingService service;LandlordService owners;
 @BeforeEach void init() throws Exception {
  jdbc=new JdbcTemplate(new DriverManagerDataSource("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;NON_KEYWORDS=USER;DB_CLOSE_DELAY=-1","sa",""));jdbc.execute("CREATE TABLE rooms(room_id VARCHAR(20) PRIMARY KEY)");jdbc.execute("CREATE TABLE user(id BIGINT PRIMARY KEY,role INT)");jdbc.execute("CREATE TABLE room_landlords(room_id VARCHAR(20),user_id BIGINT)");jdbc.update("INSERT INTO rooms VALUES('R1'),('R2')");jdbc.update("INSERT INTO user VALUES(1,1),(2,1)");jdbc.update("INSERT INTO room_landlords VALUES('R1',1),('R2',2)");
  String schema=Files.readString(Path.of("src/main/resources/schema.sql"));schema=schema.substring(schema.indexOf("CREATE TABLE IF NOT EXISTS room_listings"));for(String statement:schema.split(";"))if(!statement.isBlank())jdbc.execute(statement.replaceAll("ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci", ""));
  owners=mock(LandlordService.class);Room one=Room.builder().roomId("R1").landlordId(1L).landlordName("A").area(0f).basePrice(BigDecimal.ZERO).status("UNCONFIGURED").occupied(false).occupancyKnown(true).availableForRent(false).build();Room two=Room.builder().roomId("R2").landlordId(2L).landlordName("B").area(20f).basePrice(new BigDecimal("2000000")).status("AVAILABLE").occupied(false).occupancyKnown(true).availableForRent(true).build();when(owners.browseRooms()).thenReturn(List.of(one,two));when(owners.mine("A")).thenReturn(List.of(one));when(owners.mine("B")).thenReturn(List.of(two));doThrow(new ResponseStatusException(HttpStatus.FORBIDDEN,"Other owner")).when(owners).requireOwner("B","R1");service=new RoomListingService(jdbc,owners);
 }
 MockMultipartFile image() throws Exception {var bytes=new ByteArrayOutputStream();ImageIO.write(new BufferedImage(800,600,BufferedImage.TYPE_INT_RGB),"png",bytes);return new MockMultipartFile("file","room.png","image/png",bytes.toByteArray());}
 @Test void allRoomsRemainVisibleIncludingUnconfiguredAndNoInventoryIsCreated(){var list=service.list("tenant",false);assertEquals(2,list.size());assertEquals(false,list.getFirst().get("availableForRent"));assertEquals("R1",list.getFirst().get("title"));assertEquals(1,service.list("A",true).size());assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM rooms",Integer.class));}
 @Test void ownerCanDescribeOnlyTheirRoom(){service.describe("A","R1","Phòng 101","Có cửa sổ","Địa chỉ chủ nhà nhập");assertEquals("Có cửa sổ",service.detail("tenant",false,"R1").get("description"));assertThrows(ResponseStatusException.class,()->service.describe("B","R1","Wrong","Wrong","Wrong"));assertThrows(ResponseStatusException.class,()->service.detail("B",true,"R1"));}
 @Test void imagesPersistAndHaveProtectedThumbnails() throws Exception {String id=service.upload("A","R1",image());var original=service.photo("tenant",false,id,false);assertEquals("image/png",original.mime());assertNotNull(ImageIO.read(new ByteArrayInputStream(original.bytes())));var thumb=service.photo("tenant",false,id,true);assertEquals("image/jpeg",thumb.mime());var decoded=ImageIO.read(new ByteArrayInputStream(thumb.bytes()));assertTrue(decoded.getWidth()<=640);assertTrue(decoded.getHeight()<=480);assertThrows(ResponseStatusException.class,()->service.photo("B",true,id,false));assertEquals(1,((List<?>)service.detail("tenant",false,"R1").get("photos")).size());service.deletePhoto("A","R1",id);assertThrows(ResponseStatusException.class,()->service.photo("tenant",false,id,false));}
 @Test void nonImagesAndAnotherOwnersUploadsAreRejected() throws Exception {assertThrows(ResponseStatusException.class,()->service.upload("A","R1",new MockMultipartFile("file","fake.png","image/png","not an image".getBytes())));assertThrows(ResponseStatusException.class,()->service.upload("B","R1",image()));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM room_photos",Integer.class));}
 @Test void sixPhotoLimitAndRoomScopedDeletion() throws Exception {String first=service.upload("A","R1",image());for(int i=1;i<6;i++)service.upload("A","R1",image());assertThrows(ResponseStatusException.class,()->service.upload("A","R1",image()));assertThrows(ResponseStatusException.class,()->service.deletePhoto("B","R2",first));assertEquals(6,jdbc.queryForObject("SELECT COUNT(*) FROM room_photos",Integer.class));}
}
